//! Complete78E30 maintenance when no8C550 height setter is reached.
//! Successful plans consume noRNG; world job retirement/count and viewport
//! requests must still commit atomically. Dynamic height changes reject.
use crate::{construction_setup,construction_completion,landing};
use crate::construction_terrain::*;
#[derive(Debug,Clone,Copy,PartialEq,Eq)]
pub struct TerrainEnvironment{pub climate_center:[i16;2],pub raw_water_height:i16,pub climate:i16,pub light:[i32;3]}
#[derive(Debug,Clone,PartialEq,Eq)]
pub enum TerrainMaintenanceError{Terrain(TerrainJobError),HeightSetterRequired,UnsupportedRectangle}
impl From<TerrainJobError> for TerrainMaintenanceError{fn from(v:TerrainJobError)->Self{Self::Terrain(v)}}
#[derive(Debug,Clone,PartialEq,Eq)]
pub struct TerrainMaintenancePlan{pub before:TerrainJob,pub after:TerrainJob,pub map_after:Vec<u8>,pub viewport_invalidations:Vec<u16>,pub retirement_required:bool}
fn word(b:&[u8],p:usize)->i16{i16::from_le_bytes(b[p..p+2].try_into().unwrap())}
fn normals(map:&[u8],index:u16)->[[i32;3];2]{let mut point=[((index&127)<<8).wrapping_sub(16)as i16,((index>>7)<<8).wrapping_sub(2)as i16];std::array::from_fn(|_|{let x=(i32::from(point[0])>>8)&127;let y=(i32::from(point[1])>>8)&127;let heights=std::array::from_fn(|n|{let dx=(n&1)as i32;let dy=(n>>1)as i32;word(map,((((y+dy)&127)*128+((x+dx)&127))*14+2)as usize)});let normal=landing::landing_terrain_normal(point,heights);point[1]=point[1].wrapping_add(4);normal})}
pub fn plan_terrain_job_without_height_changes(map:&[u8],job:&TerrainJob,context:TerrainEnvironment,table:&[u8;8192])->Result<TerrainMaintenancePlan,TerrainMaintenanceError>{let TerrainEnvironment{climate_center:center,raw_water_height:water,climate,light}=context;let plan=plan_terrain_job_numeric_step(job,map)?;if !plan.heights.is_empty(){return Err(TerrainMaintenanceError::HeightSetterRequired);}let mut after=map.to_vec();let mut invalidations=Vec::new();for request in plan.maintenance{match request{TerrainMaintenanceRequest::ClassifyCell(i)=>classify_terrain_cell(&mut after,i,center,water,climate)?,TerrainMaintenanceRequest::BorderCell(i)=>repair_terrain_material_boundary(&mut after,i)?,TerrainMaintenanceRequest::BorderRectangle{min,max}=>invalidations.extend(repair_terrain_rectangle(&mut after,min,max,table)?),TerrainMaintenanceRequest::RefreshRectangle{min,max,completed}=>{if min.iter().any(|v|*v<256)||max.iter().any(|v|*v>32256){return Err(TerrainMaintenanceError::UnsupportedRectangle);}let x=i32::from(min[0]>>8)-1;let y=i32::from(min[1]>>8)-1;let width=i32::from(max[0]>>8)-i32::from(min[0]>>8)+2;let height=i32::from(max[1]>>8)-i32::from(min[1]>>8)+2;for row in 0..height{for col in 0..width{let index=((y+row)*128+x+col)as u16;let p=usize::from(index)*14;if after[p+4]==0x97{invalidations.extend(construction_setup::prepare_terrain_site_cell(&mut after,index,table)?);}if completed{let mut seed=0;construction_completion::complete_terrain_cell(&mut after,index,water,&mut seed,|_,_,_,_|Err(TerrainJobError::InvalidHeight)).map_err(|_|TerrainMaintenanceError::HeightSetterRequired)?;}let shade=terrain_shade_value(after[p+5],word(&after,p+2),water,normals(&after,index),light)?;after[p..p+2].copy_from_slice(&shade.to_le_bytes());}}}}}Ok(TerrainMaintenancePlan{before:*job,after:plan.after,map_after:after,viewport_invalidations:invalidations,retirement_required:plan.retirement_required})}
